                    if st.button("Siguiente \u27a1\ufe0f", key="btn_nav_next_h2", use_container_width=True, disabled=(idx_fac_sel >= len(opciones_fac) - 1)):
                        nuevo_i = min(len(opciones_fac) - 1, idx_fac_sel + 1)
